        dict(title=T('Bẫy và mở rộng: phản lực trực tiếp/gián tiếp, định nghĩa, hiệu suất, tầm bay', 'Pitfalls and extensions: direct/indirect reaction, definitions, efficiencies, range'), bullets=[T('Slide tr.43–47 + bổ sung từ sách', 'Slides pp.43–47 + book supplements'), T('Gas generator, APU', 'Gas generator, APU'), T('Hiệu suất tổng, TSFC, Breguet', 'Overall efficiency, TSFC, Breguet')], slides=p4),
